const collectedFor=(kind,id)=>(state.data.service_collections||[]).filter(c=>c[kind]===id).reduce((n,c)=>{const s=state.data.sales.find(s=>s.id===c.sale_id);return n+(s&&s.status!=='VOID'?Number(s.total):0)},0);
function collectionFields(){return methods.filter(([id])=>id).map(([id,label])=>inputField(id,label+' · importe','number','',false)).join('')+inputField('commission_rate','Comisión % (vacío: automática)','number','',false);}
function collectionPayments(f){return methods.filter(([id])=>id&&Number(f[id])>0).map(([method])=>({method,amount:Number(f[method]),...(f.commission_rate===''?{}:{commission_rate:Number(f.commission_rate)})}));}
