function appointmentDetail(id){
 const a=state.data.appointments.find(a=>a.id===id);const c=state.data.customers.find(c=>c.id===a.customer_id);const date=new Date(a.starts_at).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires'});
 const text=`Hola ${c?.full_name||''}, te recordamos tu turno de Lashby Academia el ${date}.`;
 modal(`<div class="modal-head"><h3>Turno de ${esc(c?.full_name)}</h3><button class="icon-btn" data-close>×</button></div><p>${esc(date)} · ${esc(a.status)}</p><p>Total ${a.total_amount==null?'Pendiente':money(a.total_amount)} · Cobrado ${money(collectedFor('appointment_id',id))}</p><div class="toolbar"><button class="btn btn-primary" id="collect-appointment">Registrar seña / saldo</button><button class="btn btn-soft" id="edit-appointment">Estado y horario</button><button class="btn btn-soft" id="plan-reminder">Programar recordatorio</button></div><h3>Enviar recordatorio</h3><p>Estos botones abren el mensaje; confirmá el envío en WhatsApp o en tu correo.</p>${c?.phone?`<a class="btn btn-soft" href="https://wa.me/${esc(c.phone.replace(/\D/g,''))}?text=${encodeURIComponent(text)}" target="_blank" rel="noopener noreferrer">WhatsApp</a>`:'<p>Agregá WhatsApp a la ficha de la clienta.</p>'}${c?.email?`<a class="btn btn-soft" href="mailto:${esc(c.email)}?subject=${encodeURIComponent('Recordatorio Lashby')}&body=${encodeURIComponent(text)}">Correo</a>`:'<p>Agregá correo a la ficha de la clienta.</p>'}<h3>Recordatorios programados</h3>${(state.data.appointment_reminders||[]).filter(r=>r.appointment_id===id).map(r=>`<p>${esc(r.channel)} · ${esc(new Date(r.scheduled_at).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires'}))} · ${esc(r.status)} ${r.status==='PENDING'?`<button class="btn btn-soft" data-reminder-sent="${r.id}">Confirmar enviado</button>`:''}</p>`).join('')}`);
 document.querySelector('#collect-appointment').onclick=()=>operationForm('Cobro de servicio',collectionFields(),f=>callOperation('collect_service',{p_payload:{appointment_id:id,payments:collectionPayments(f)}}));
 document.querySelector('#edit-appointment').onclick=()=>operationForm('Modificar turno',selectField('status','Estado',[['RESERVED','Reservado'],['COMPLETED','Realizado'],['CANCELLED','Cancelado'],['NO_SHOW','Ausente']],a.status)+inputField('starts_at','Nuevo horario Argentina','datetime-local','',false)+inputField('total_amount','Importe total','number',a.total_amount??'',false)+inputField('notes','Notas','text',a.notes,false),f=>callOperation('update_appointment',{p_id:id,p_payload:{status:f.status,starts_at:f.starts_at?argentinaTimestamp(f.starts_at):null,total_amount:f.total_amount===''?null:Number(f.total_amount),notes:f.notes}}));
 document.querySelector('#plan-reminder').onclick=()=>operationForm('Programar recordatorio',selectField('channel','Canal',[['WHATSAPP','WhatsApp'],['EMAIL','Correo']])+inputField('scheduled_at','Fecha y hora Argentina','datetime-local'),f=>saveRecord('appointment_reminders',{appointment_id:id,channel:f.channel,scheduled_at:argentinaTimestamp(f.scheduled_at),status:'PENDING'}));
 document.querySelectorAll('[data-reminder-sent]').forEach(b=>b.onclick=async()=>{try{await saveRecord('appointment_reminders',{status:'SENT',sent_at:new Date().toISOString()},b.dataset.reminderSent);closeModal();await refreshData()}catch(e){toast(e.message)}});
}

function cartForSale(){return applyTotalDiscount(state.cart,state.saleDiscount)}
function saleAdjustments(){
 const update=()=>{try{if(state.payments.length===1)syncCheckout();salePage();hydrateIcons()}catch(e){toast(e.message)}};
 document.querySelector('#sale-discount').onchange=e=>{const old=state.saleDiscount;state.saleDiscount=Number(e.target.value);try{cartForSale()}catch(err){state.saleDiscount=old;toast(err.message)}update()};
 document.querySelectorAll('[data-line-discount]').forEach(i=>i.onchange=()=>{const l=state.cart.find(l=>l.key===i.dataset.lineDiscount);const d=Number(i.value);if(d<0||d>l.unit_price*l.quantity)return toast('Descuento inválido');l.discount=d;state.saleDiscount=0;update()});
 document.querySelectorAll('[data-pay-rate]').forEach(i=>i.oninput=()=>{const p=state.payments[Number(i.dataset.payRate)];if(i.value==='')delete p.commission_rate;else p.commission_rate=Number(i.value)});
 document.querySelector('#sale-promo').onchange=e=>{const promo=state.data.promotions.find(p=>p.id===e.target.value);if(!promo)return;state.cart.forEach(l=>{if(!promo.product_id||promo.product_id===l.product_id)l.discount=Math.round(l.quantity*l.unit_price*Number(promo.discount_percent))/100});state.saleDiscount=0;update()};
}
function dashboardTools(){
 if(state.data.profile.role!=='ADMIN')return;
 const r=periodSummary(state.data,todayISO());const activeLots=state.data.stock.filter(l=>state.data.receipts.find(s=>s.id===l.receipt_id)?.status==='ACTIVE'&&Number(l.remaining_quantity)>0);
 const unknown=activeLots.some(l=>l.unit_cost==null)||state.data.products.some(p=>Number(p.stock)<0);
 const valuation=unknown?null:activeLots.reduce((n,l)=>n+Number(l.remaining_quantity)*Number(l.unit_cost),0);
 const show=v=>v==null?'Pendiente':money(v);
 const metrics=[['Margen bruto',show(r.gross)],['Resultado operativo',show(r.operating)],['Margen operativo %',r.operating==null?'Pendiente':r.revenue?(r.operating/r.revenue*100).toFixed(2)+'%':'—'],['Stock valorizado FIFO',show(valuation)],['Flujo después de cuotas',show(r.flowAfterLoans)],['Compras pagadas',money(r.purchases)],['Gastos',money(r.expenses)],['Cuotas',money(r.loans)]];
 const by=new Map();
 for(const product of state.data.products){const ids=new Set(state.data.sales.flatMap(s=>s.sale_lines||[]).filter(l=>l.product_id===product.id).map(l=>l.id));if(!ids.size)continue;const productData={...state.data,sales:state.data.sales.map(s=>{const lines=(s.sale_lines||[]).filter(l=>ids.has(l.id));return {...s,sale_lines:lines,total:lines.reduce((n,l)=>n+Number(l.line_total),0)}}).filter(s=>s.sale_lines.length),returns:(state.data.returns||[]).map(r=>({...r,return_lines:(r.return_lines||[]).filter(l=>ids.has(l.sale_line_id))})),expenses:[]};const stat=periodSummary(productData,'');by.set(product.id,{name:product.name,revenue:stat.revenue,cogs:stat.cogs,pending:stat.pending});}
 const issues=state.data.products.filter(p=>['SIMPLE','KIT_OWN_STOCK'].includes(p.product_type)).flatMap(p=>{const lots=activeLots.filter(l=>l.product_id===p.id).reduce((n,l)=>n+Number(l.remaining_quantity),0);return Math.abs(lots-Math.max(0,Number(p.stock)))>.001?[`${p.name}: lotes disponibles ${lots}, stock neto ${p.stock}. Revisar variantes y cantidades pendientes.`]:[]});
 document.querySelector('#content').insertAdjacentHTML('beforeend',`<h3>Rentabilidad y flujo del día</h3><section class="metric-grid">${metrics.map(([label,value])=>`<article class="metric"><div class="metric-top">${label}</div><div class="metric-value">${value}</div></article>`).join('')}</section><article class="card"><h3>Rentabilidad por producto · histórico</h3><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Ventas</th><th>COGS FIFO</th><th>Margen bruto</th></tr></thead><tbody>${[...by.values()].map(p=>`<tr><td>${esc(p.name)}</td><td>${money(p.revenue)}</td><td>${p.pending?'Pendiente':money(p.cogs)}</td><td>${p.pending?'Pendiente':money(p.revenue-p.cogs)}</td></tr>`).join('')||'<tr><td colspan="4">Sin ventas</td></tr>'}</tbody></table></div></article><article class="card"><h3>Control de consistencia de stock</h3>${issues.map(i=>`<p>${esc(i)}</p>`).join('')||'<p>No se detectaron diferencias en este control.</p>'}</article>`);
}

function returnForm(id){
 if(!adminOnly())return;
 const sale=state.data.sales.find(s=>s.id===id);const returned=(state.data.returns||[]).filter(r=>r.sale_id===id&&r.status==='ACTIVE').flatMap(r=>r.return_lines||[]);
 const available=(sale.sale_lines||[]).filter(l=>['SIMPLE','KIT_COMPONENTS','KIT_OWN_STOCK'].includes(state.data.products.find(p=>p.id===l.product_id)?.product_type)).map(l=>({...l,available:Number(l.quantity)-returned.filter(r=>r.sale_line_id===l.id).reduce((n,r)=>n+Number(r.quantity),0)})).filter(l=>l.available>0);
 if(!available.length)return toast('Esta venta no tiene productos físicos pendientes de devolver');
 modal(`<div class="modal-head"><h3>Cambio / devolución · ${esc(sale.number)}</h3><button class="icon-btn" data-close>×</button></div><p>Se utiliza el precio histórico, con sus descuentos. La mercadería vuelve al stock y su importe queda como saldo a favor. No se devuelve efectivo.</p><form id="return-form" class="form-grid">${selectField('customer_id','Clienta para el saldo a favor',[['','Seleccionar'],...state.data.customers.filter(c=>!sale.customer_id||c.id===sale.customer_id).map(c=>[c.id,c.full_name])],sale.customer_id||'')}${inputField('reason','Motivo')}${available.map(l=>`<div class="field span-2"><label>${esc(l.product_name)} · ${esc(l.unit_label||'unidades')} · disponible ${l.available} · importe de la línea ${money(l.line_total)}</label><input type="number" name="${l.id}" min="0" max="${l.available}" step=".001" value="0"></div>`).join('')}<div class="modal-actions span-2"><button class="btn btn-soft" type="button" id="return-credit">Solo devolver y guardar saldo</button><button class="btn btn-primary">Elegir reemplazo</button></div></form>`);
 const get=()=>{const form=document.querySelector('#return-form');if(!form.reportValidity())throw new Error('Completá la clienta y el motivo');const f=Object.fromEntries(new FormData(form));const lines=available.filter(l=>Number(f[l.id])>0).map(l=>({sale_line_id:l.id,quantity:Number(f[l.id])}));if(!lines.length)throw new Error('Indicá al menos una cantidad');const value=lines.reduce((n,r)=>{const l=available.find(l=>l.id===r.sale_line_id);const oldValue=returned.filter(x=>x.sale_line_id===l.id).reduce((a,x)=>a+Number(x.returned_value),0);return n+(r.quantity===l.available?Number(l.line_total)-oldValue:Math.round(Number(l.line_total)*r.quantity/Number(l.quantity)*100)/100)},0);return {sale_id:id,customer_id:f.customer_id,reason:f.reason,lines,value}};
 document.querySelector('#return-form').onsubmit=e=>{e.preventDefault();try{const f=get();resetCheckout();state.customerId=f.customer_id;state.exchange={saleId:id,number:sale.number,reason:f.reason,lines:f.lines,value:f.value};state.route='sale';closeModal();renderShell()}catch(err){toast(err.message)}};
 document.querySelector('#return-credit').onclick=async e=>{let f;try{f=get()}catch(err){return toast(err.message)}e.currentTarget.disabled=true;try{await callOperation('return_sale',{p_payload:f});closeModal();await refreshData();toast('Reingreso registrado y saldo a favor guardado')}catch(err){e.target.disabled=false;toast(err.message)}};
}
function showReturns(){
 const rows=state.data.returns||[];
 document.querySelector('#content').insertAdjacentHTML('beforeend',`<article class="card"><h3>Cambios y devoluciones</h3>${rows.map(r=>`<div class="cart-line"><div><strong>${esc(state.data.sales.find(s=>s.id===r.sale_id)?.number||r.sale_id)}</strong><p>${esc(businessDate(r.created_at))} · ${esc(state.data.customers.find(c=>c.id===r.customer_id)?.full_name)} · ${money((r.return_lines||[]).reduce((n,l)=>n+Number(l.returned_value),0))} · ${esc(r.status)}</p><p>${esc(r.notes||'')}</p>${r.replacement_sale_id?`<p>Reemplazo: ${esc(state.data.sales.find(s=>s.id===r.replacement_sale_id)?.number||'Venta vinculada')}</p>`:''}</div>${r.status==='ACTIVE'&&state.data.profile.role==='ADMIN'?`<button class="btn btn-soft" data-void-return="${r.id}">Anular cambio</button>`:''}</div>`).join('')||'<p>Sin devoluciones</p>'}</article>`);
 document.querySelectorAll('[data-void-return]').forEach(b=>b.onclick=()=>operationForm('Anular cambio / devolución',inputField('reason','Motivo')+'<p>Si hubo venta de reemplazo o se usó el saldo, primero hay que anular esas ventas. Si se consumió el stock reingresado, también requiere revisión.</p>',f=>callOperation('void_return',{p_id:b.dataset.voidReturn,p_reason:f.reason})));
}
